#!/usr/bin/env python3
"""Generates the golden maps in tests/mapformat/golden/ (deterministic: re-running gives byte-identical files).

    python tools/mapformat/make_golden.py [--out DIR] [--check]

--check compares the generated bytes with the files on disk instead of writing (exit 1 on a difference).
The valid maps are also dumped (<name>.dump.txt) and their simHash written (<name>.simhash).
"""
import argparse
import contextlib
import hashlib
import os
import struct
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import golden_content as G                                   # noqa: E402
import golden_world3d as G3                                  # noqa: E402
from mapfmt import chunks as C                               # noqa: E402
from mapfmt import scatter                                   # noqa: E402
from mapfmt.builder import MapBuilder                        # noqa: E402
from mapfmt.chunkdef import CHUNKS                           # noqa: E402
from mapfmt.container import (ENTRY_FMT, ENTRY_SIZE, F_REQUIRED, HEADER_SIZE, crc32)    # noqa: E402
from mapfmt.dump import dump_text                            # noqa: E402
from mapfmt.loadmap import load_map                          # noqa: E402

ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
DEFAULT_OUT = os.path.join(ROOT, "tests", "mapformat", "golden")


def guid(name):
    return hashlib.sha256(("faf-re golden " + name).encode()).digest()[:16]


def make(name, chunks, container=3, extra_required=0, extra_optional=0, render_required=0, raw=()):
    b = MapBuilder(container, guid(name))
    for cid, inst, d, compress in chunks:
        b.add(cid, d, inst, compress)
    for r in raw:
        b.add_raw(*r[:2], **r[2])
    return b.build(render_required, extra_required, extra_optional), b


@contextlib.contextmanager
def unchecked(cid):
    """Encode a chunk whose own validation would refuse it (negative tests only)."""
    schema = CHUNKS[cid].schema
    saved, schema.check = schema.check, None
    try:
        yield
    finally:
        schema.check = saved


def patch_header_crc(data):
    d = bytearray(data)
    d[124:128] = struct.pack("<I", crc32(bytes(d[:124])))
    return bytes(d)


def patch_dir(data, fn):
    """Rewrite directory entries (lists of the ENTRY_FMT fields) and fix dirCrc + header CRC."""
    d = bytearray(data)
    dir_off, count = struct.unpack_from("<QI", d, 24)
    ents = [list(struct.unpack_from(ENTRY_FMT, d, dir_off + i * ENTRY_SIZE)) for i in range(count)]
    fn(ents)
    blob = b"".join(struct.pack(ENTRY_FMT, *e) for e in ents)
    d[dir_off:dir_off + len(blob)] = blob
    d[36:40] = struct.pack("<I", crc32(blob))
    return patch_header_crc(bytes(d))


# entry fields: 0 id, 1 version, 2 flags, 3 instance, 4 crc, 5 offset, 6 stored, 7 raw, 8 reserved
def entry(ents, cid):
    return [e for e in ents if e[0] == cid.encode()][0]


def build_all():
    out = {}

    def valid(name, data):
        out[name + ".fmap"] = data
        out[name + ".dump.txt"] = dump_text(data).encode("ascii")
        out[name + ".simhash"] = (load_map(data).container.sim_hash.hex() + "\n").encode("ascii")

    # ---- extended_min
    mn, _ = make("extended_min", G.extended_min())
    valid("extended_min", mn)

    # ---- extended_full (DRVD needs the raw bytes of its inputs, so encode those first)
    chunks, vals = G.extended_full()
    dec = dict((c[0], c[2]) for c in chunks if c[1] == 0)
    ctx = C.context_from(dec)
    raw = lambda cid: C.encode_chunk(cid, dec[cid], ctx)           # noqa: E731
    chunks += G.drvd_chunks(raw("HGHT"), [raw(c) for c in ("GRID", "HGHT", "GPLY", "WBOD", "LEVL", "PLAY")], vals)
    ext_chunks = list(chunks)
    full, fb = make("extended_full", chunks)
    valid("extended_full", full)

    # ---- full3d_full: everything above plus the Full3D chunks, container 4
    f3, f3b = make("full3d_full", ext_chunks + G3.world3d_chunks(), container=4)
    valid("full3d_full", f3)

    # ---- extended_classic_equiv
    ce, _ = make("extended_classic_equiv", G.classic_equiv())
    valid("extended_classic_equiv", ce)

    # ---- chunks the reader does not know
    unk_opt, _ = make("unknown_optional_chunk", G.extended_min(), raw=[("ZZZO", b"optional chunk of a later revision", {"instance": 0, "flags": 0})])
    valid("unknown_optional_chunk", unk_opt)

    # ---- negative files
    out["bad_magic.fmap"] = b"X" + mn[1:]
    d = bytearray(mn)
    d[4:8] = struct.pack("<I", 5)
    out["bad_container_5.fmap"] = patch_header_crc(bytes(d))
    d = bytearray(mn)
    d[104] ^= 0x01                      # a reserved header byte, CRC left alone
    out["bad_header_crc.fmap"] = bytes(d)
    out["truncated.fmap"] = mn[:-100]
    d = bytearray(mn)
    dir_off = struct.unpack_from("<Q", d, 24)[0]
    d[dir_off + 40] ^= 0x01             # reserved field of the first entry, dirCrc left alone
    out["bad_dir_crc.fmap"] = bytes(d)
    d = bytearray(mn)
    dir_off, count = struct.unpack_from("<QI", d, 24)
    ents = [struct.unpack_from(ENTRY_FMT, d, dir_off + i * ENTRY_SIZE) for i in range(count)]
    grid_off = [e for e in ents if e[0] == b"GRID"][0][5]
    d[grid_off + 3] ^= 0x40             # inside GRID's stored bytes
    out["bad_chunk_crc.fmap"] = bytes(d)

    def far(ents):
        entry(ents, "META")[5] = struct.unpack_from("<Q", mn, 24)[0] + 4096
    out["chunk_out_of_range.fmap"] = patch_dir(mn, far)
    zz, _ = make("unknown_required_chunk", G.extended_min(), raw=[("ZZZZ", b"i am required and unknown", {"instance": 0, "flags": F_REQUIRED})])
    out["unknown_required_chunk.fmap"] = zz
    uf, _ = make("unsupported_required_feature", G.extended_min(), extra_required=1 << 63)
    out["unsupported_required_feature.fmap"] = uf

    def bomb(ents):
        e = entry(ents, "HGHT")
        e[7] = e[6] * 2000              # declared rawSize beyond deflate's 1:1032 maximum
    out["inflate_bomb.fmap"] = patch_dir(mn, bomb)

    bad = G.extended_min()
    bad = [(c, i, dict(dd), z) for c, i, dd, z in bad]
    for k, (c, i, dd, z) in enumerate(bad):
        if c == "GPLY":
            ids = bytearray(G.W * G.H)
            ids[100] = 5                # id 5 is not in the surface table
            dd["ids"] = {"predictor": 0, "data": bytes(ids)}
            bad[k] = (c, i, dd, z)
    with unchecked("GPLY"):
        out["gpl_bad_surface_id.fmap"], _ = make("gpl_bad_surface_id", bad)

    # ---- the scatter expectation of extended_full's first SCAT layer
    layer = dec["SCAT"]["layers"][0]
    inst = scatter.generate_layer(layer, 0, G.W, G.H, scatter.FlatSampler(10.0, 1.0))
    count, digest = scatter.summary(inst)
    out["scatter_expected.txt"] = (
        "file = extended_full.fmap\nlayer = 0\n"
        "sampler = flat height 10.0, slope 0, material 0, surface 0, no holes, density map constant 1.0\n"
        "grid = %dx%d cells, cellSize 1.0, origin 0,0\n"
        "record = u32 variant, f32 x, z, y, scale, yawDeg, tint (little endian)\n"
        "count = %d\nsha256 = %s\n" % (G.W, G.H, count, digest)).encode("ascii")
    return out


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--out", default=DEFAULT_OUT)
    ap.add_argument("--check", action="store_true", help="compare with the files on disk instead of writing")
    a = ap.parse_args()
    files = build_all()
    bad = 0
    for name, data in sorted(files.items()):
        path = os.path.join(a.out, name)
        if a.check:
            same = os.path.exists(path) and open(path, "rb").read() == data
            if not same:
                print("DIFFERS", name)
                bad += 1
        else:
            os.makedirs(a.out, exist_ok=True)
            with open(path, "wb") as f:
                f.write(data)
            print("wrote %-40s %7d bytes" % (name, len(data)))
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())
